-- Items untuk Pesanan Sefza

-- Histori Point Sefza (20 Transaksi @ 20 Poin)
SELECT UUID(), '00000000-0000-0000-0000-000000000002', id, 'earned', 20, 'Points from purchase', created_at 
FROM orders WHERE user_id = '00000000-0000-0000-0000-000000000002';


-- =========================================================
-- 7. SEED ORDERS UNTUK ALAM (30 Orders tersebar 3 bulan)
-- =========================================================

-- Items untuk Pesanan Alam (Otomatis mencocokkan harga Final Amount)
SELECT UUID(), id, '22222222-0000-0000-0000-000000000001', 1, 18000, created_at FROM orders WHERE user_id = '00000000-0000-0000-0000-000000000003' AND final_amount = 18000 UNION
SELECT UUID(), id, '22222222-0000-0000-0000-000000000002', 1, 25000, created_at FROM orders WHERE user_id = '00000000-0000-0000-0000-000000000003' AND final_amount = 25000 UNION
SELECT UUID(), id, '22222222-0000-0000-0000-000000000003', 1, 28000, created_at FROM orders WHERE user_id = '00000000-0000-0000-0000-000000000003' AND final_amount = 28000 UNION
SELECT UUID(), id, '22222222-0000-0000-0000-000000000004', 1, 20000, created_at FROM orders WHERE user_id = '00000000-0000-0000-0000-000000000003' AND final_amount = 20000;

-- Histori Point Alam (30 Poin transaksi @ 20 poin)
